// ═══════════════════════════════════════════════════════════════════════════
// ΓΛΩΣΣΕΣ — έξι, και η κάθε μία δικαιολογείται από δεδομένα (GA4 + 9.830 μέλη).
//
//   EL  Ελλάδα        9,8% καθαρής επισκεψιμότητας · 1.404 μέλη
//   EN  διεθνές       53% των σελίδων που διαβάζονται
//   BG  Βουλγαρία     28,1% · 2.101 μέλη   ← η #1 αγορά
//   SR  Σερβία        27,6% · 1.555 μέλη   ← η #2 (καλύπτει και Β. Μακεδονία)
//   DE  Γερμανία      3,6% · 701 μέλη (+ Αυστρία, Ελβετία)
//   RO  Ρουμανία      8,3% · 975 μέλη      ← ΝΕΑ: η #4 αγορά, χωρίς γλώσσα ως σήμερα
//
// ⚠️ Τα ρωσικά ΔΕΝ μπαίνουν προς το παρόν: 0,6% γλώσσας browser, εκτός 25 πρώτων
//    χωρών, 16 μέλη. Εκκρεμεί έλεγχος του ξεχωριστού halkidikiproperties.ru
//    πριν παρθεί οριστική απόφαση.
// ═══════════════════════════════════════════════════════════════════════════
//   TR  Τουρκία       2.923 αναζ./μήνα · `yunanistan satılık ev` 722/μ με KD 0
//                     ⚠️ μεγάλο μέρος ΕΝΗΜΕΡΩΤΙΚΟ («τιμές σπιτιών») — 28 δευτ. παραμονής σήμερα
//   HE  Ισραήλ        2.739 αναζ./μήνα με KD 0-2 · 365 μέλη ήδη, χωρίς να τους μιλάμε
//                     🔴 RTL — δες `isRTL` παρακάτω και το `dir` στο Base.astro
//   RU  Ρωσία         διαφημιζόμαστε ΗΔΗ σε Prian.ru και Tranio — το κοινό υπάρχει
//                     ⚠️ μόνο 16 μέλη και 0,6% γλώσσας browser· ΠΡΙΝ κριθεί, δες το ξεχωριστό .ru
export const LANGS = ['el', 'en', 'bg', 'sr', 'de', 'ro', 'tr', 'he', 'ru'] as const;
export type Lang = (typeof LANGS)[number];
export const DEFAULT_LANG: Lang = 'el';

/**
 * Γλώσσες που γράφονται από δεξιά προς τα αριστερά.
 * Καθορίζει το `dir` του <html> — και μαζί ΟΛΗ τη γεωμετρία της σελίδας, γιατί
 * το CSS χρησιμοποιεί logical properties (margin-inline, padding-inline, start/end).
 */
export const RTL: readonly Lang[] = ['he'];
export const isRTL = (lang: Lang): boolean => RTL.includes(lang);

/** Το prefix του URL. Η ελληνική είναι η προεπιλογή και δεν παίρνει prefix. */
export function prefix(lang: Lang): string {
  return lang === DEFAULT_LANG ? '' : `/${lang}`;
}

/** Τα slugs διατηρούνται 1:1 με το σημερινό site — μηδέν σπασμένο URL στο cutover. */
export const SLUG: Record<Lang, { list: string; property: string; projects: string }> = {
  el: { list: 'ακινητα',      property: 'ακινητο',     projects: 'εργα' },
  en: { list: 'properties',   property: 'property',    projects: 'projects' },
  bg: { list: 'Имоти',        property: 'Имоти',       projects: 'проекти' },
  sr: { list: 'nekretnina',   property: 'nekretnine',  projects: 'projekti' },
  de: { list: 'immobilien',   property: 'immobilie',   projects: 'projekte' },
  ro: { list: 'proprietati',  property: 'proprietate', projects: 'proiecte' },
  // 🪤 ΛΑΤΙΝΙΚΑ SLUGS ΚΑΙ ΓΙΑ ΤΑ ΕΒΡΑΪΚΑ. Το εβραϊκό αλφάβητο στο URL γίνεται
  //    punycode/percent-encoding που είναι δυσανάγνωστο, δεν αντιγράφεται σωστά
  //    και σπάει σε RTL περιβάλλον όταν μπλέκεται με λατινικό domain.
  tr: { list: 'emlak',        property: 'emlak',       projects: 'projeler' },
  he: { list: 'nadlan',       property: 'neches',      projects: 'projects' },
  // Λατινικά και για τα ρωσικά: κυριλλικό slug γίνεται δυσανάγνωστο percent-encoding
  // στη γραμμή διευθύνσεων και σπάει όταν αντιγραφεί σε chat.
  ru: { list: 'nedvizhimost', property: 'obekt',       projects: 'proekty' },
};

export function listUrl(lang: Lang): string {
  return `${prefix(lang)}/${SLUG[lang].list}`;
}
export function propertyUrl(lang: Lang, id: string): string {
  return `${prefix(lang)}/${SLUG[lang].property}/${id}`;
}

/**
 * Η σελίδα των ΕΡΓΩΝ — τι έχουμε χτίσει.
 * George (28/7): «για τα projects που έχουμε χτίσει στο παρελθόν θα κάνουμε
 * ειδική σελίδα που θα οδηγεί εκεί.» Άρα το μπλοκ της αρχικής μένει «τι
 * μπορούμε» και η ΑΠΟΔΕΙΞΗ (φωτογραφίες, ονόματα, μεγέθη) ζει εδώ.
 * ⏳ Η σελίδα ΔΕΝ έχει χτιστεί ακόμα — ο σύνδεσμος δίνει 404, όπως όλοι οι
 *    εσωτερικοί σύνδεσμοι σήμερα. Μπαίνει στο sitemap ΜΟΝΟ όταν σερβίρει 200.
 */
export function projectsUrl(lang: Lang): string {
  return `${prefix(lang)}/${SLUG[lang].projects}`;
}

/**
 * hreflang — το #1 τεχνικό κενό του σημερινού site (μηδέν σε εξάγλωσσο site).
 * ⚠️ ΜΟΝΟ γλώσσες που ΟΝΤΩΣ σερβίρονται (δες `PUBLISHED` πιο κάτω).
 */
export function hreflangs(path = '/'): { lang: string; href: string }[] {
  const clean = path === '/' ? '' : path;
  const out: { lang: string; href: string }[] = PUBLISHED.map((l) => ({ lang: l, href: `${prefix(l)}${clean}` || '/' }));
  out.push({ lang: 'x-default', href: `${prefix('en')}${clean}` });
  return out;
}

/**
 * 🌍 HREFLANG ΓΙΑ ΣΕΛΙΔΕΣ ΜΕ ΔΙΑΦΟΡΕΤΙΚΟ SLUG ΑΝΑ ΓΛΩΣΣΑ.
 *
 * 🪤 ΓΙΑΤΙ ΔΕΝ ΑΡΚΕΙ ΤΟ `hreflangs()`. Εκείνο κολλάει **το ίδιο string** σε κάθε
 *    πρόθεμα. Δουλεύει για την αρχική (path = «/»), αλλά η λίστα λέγεται αλλιώς
 *    σε κάθε γλώσσα: `ακινητα` · `properties` · `Имоти` · `nekretnina` ·
 *    `nedvizhimost` · `nadlan`… Μια κλήση `hreflangs('/ακινητα')` θα παρήγε
 *    `/en/ακινητα`, `/bg/ακινητα`, `/he/ακινητα` — **δέκα URL που δίνουν 404,
 *    δηλωμένα ως εναλλακτικές μεταξύ τους**.
 *
 *    Και δεν είναι «απλώς σπασμένοι σύνδεσμοι»: όταν ένα σύμπλεγμα hreflang δεν
 *    είναι αμοιβαία έγκυρο, η Google **απορρίπτει ολόκληρο το σύμπλεγμα** — άρα
 *    θα χάναμε τη διεθνοποίηση και για τις εννέα γλώσσες, σιωπηλά.
 *
 * @param build δέχεται τη γλώσσα και επιστρέφει το ΠΛΗΡΕΣ path της, με πρόθεμα.
 */
export function hreflangsBy(build: (l: Lang) => string, only?: readonly Lang[]): { lang: string; href: string }[] {
  // `only` (B-16): a page with its own text in some languages lists just those — an English
  // fallback served under /bg/… is not a Bulgarian version. x-default stays English when it exists.
  const langs = only ? PUBLISHED.filter((l) => only.includes(l)) : PUBLISHED;
  const out: { lang: string; href: string }[] = langs.map((l) => ({ lang: l, href: build(l as Lang) || '/' }));
  const xdef = langs.includes('en') ? 'en' : langs[0];
  if (xdef) out.push({ lang: 'x-default', href: build(xdef) });
  return out;
}

type Dict = Record<string, string>;

