    'ab.close': 'Всяка стъпка се извършва от професионалист, който я е правил стотици пъти, по процедура, която не се променя от клиент на клиент. Не поемате риск, който не сме проверили преди вас.',
    'ab.cta': 'Свържете се с нас',
